INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle IPv6-Adressen 128 Bit lang?', 2, '[{"text": "Ja", "correct": true, "because": "Standardlänge für IPv6"}, {"text": "Nein", "correct": false, "because": "Keine kürzeren Varianten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Hauptunterschied zwischen IPv4- und IPv6-Headern?', 3, '[{"text": "Feste Länge bei IPv6", "correct": true, "because": "40 Byte, keine Optionen"}, {"text": "Kleinere Größe bei IPv6", "correct": false, "because": "Größer als IPv4"}, {"text": "Mehr Checksums bei IPv6", "correct": false, "because": "Keine Checksumme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Felder finde ich im IPv6-Header?', 5, '[{"text": "Source Address", "correct": true, "because": "Absenderadresse"}, {"text": "Hop Limit", "correct": true, "because": "Begrenzt Weiterleitung"}, {"text": "Checksum", "correct": false, "because": "Nicht enthalten"}, {"text": "Fragment Offset", "correct": false, "because": "Nur bei Fragmentierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv6 hat keine Fragmentierung im Header. b) Es nutzt 64-Bit-Adressen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "128 Bit, nicht 64"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim IPv6-Header?', 4, '[{"text": "Traffic Class", "correct": false, "because": "QoS-relevant"}, {"text": "Next Header", "correct": false, "because": "Protokollfolge"}, {"text": "Time to Live", "correct": true, "because": "Ersetzt durch Hop Limit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob IPv6-Adressen immer hexadezimal sind?', 2, '[{"text": "Ja", "correct": true, "because": "Notation in Hex"}, {"text": "Nein", "correct": false, "because": "Keine Dezimalform"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feld zeigt die nächste Protokollebene an?', 3, '[{"text": "Next Header", "correct": true, "because": "Verweist auf Folgeprotokoll"}, {"text": "Flow Label", "correct": false, "because": "QoS-Markierung"}, {"text": "Hop Limit", "correct": false, "because": "Lebensdauer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat der IPv6-Header?', 5, '[{"text": "40 Byte Größe", "correct": true, "because": "Feste Länge"}, {"text": "Keine Checksumme", "correct": true, "because": "Höhere Schichten prüfen"}, {"text": "Variable Länge", "correct": false, "because": "Fixiert"}, {"text": "Portnummern", "correct": false, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) IPv6-Adressen sind 128 Bit. b) Der Header ist kleiner als bei IPv4. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Header ist größer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht im IPv6-Header?', 4, '[{"text": "Source Address", "correct": false, "because": "Absender nötig"}, {"text": "Hop Limit", "correct": false, "because": "Lebensdauer"}, {"text": "Optionsfeld", "correct": true, "because": "In IPv4, nicht IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat IPv6 eine Checksumme im Header?', 2, '[{"text": "Nein", "correct": true, "because": "Entfällt zugunsten Effizienz"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen finde ich in einer IPv6-Adresse?', 4, '[{"text": "Netzwerkpräfix", "correct": true, "because": "Erste 64 Bit"}, {"text": "Interface-ID", "correct": true, "because": "Letzte 64 Bit"}, {"text": "Portnummer", "correct": false, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IPv6-Adressen kürzer als IPv4 sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "128 Bit vs. 32 Bit"}, {"text": "Ja", "correct": false, "because": "Missverständnis Länge"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Lesen eines IPv6-Headers?', 3, '[{"text": "Next Header", "correct": true, "because": "Nächste Ebene erkennen"}, {"text": "Flow Label", "correct": false, "because": "QoS optional"}, {"text": "Payload Length", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv6 hat 128-Bit-Adressen. b) Der Header ist variabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Header ist fest"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der IPv6-Header?', 5, '[{"text": "Einfachere Verarbeitung", "correct": true, "because": "Feste Länge"}, {"text": "Keine Fragmentierung", "correct": true, "because": "Router entlastet"}, {"text": "Kleinere Größe", "correct": false, "because": "Größer als IPv4"}, {"text": "Mehr Optionen", "correct": false, "because": "Optionsfeld weg"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim IPv6-Header unwichtig?', 3, '[{"text": "Hop Limit", "correct": false, "because": "Lebensdauer nötig"}, {"text": "Source Address", "correct": false, "because": "Absender essenziell"}, {"text": "Fragment Identifier", "correct": true, "because": "Nur bei Fragmentierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der IPv6-Header 32 Byte groß?', 3, '[{"text": "Nein", "correct": true, "because": "40 Byte fest"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob IPv6-Adressen Subnetze enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Präfix definiert Subnetz"}, {"text": "Nein", "correct": false, "because": "Teil der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feld steuert die Paketlebensdauer?', 4, '[{"text": "Hop Limit", "correct": true, "because": "Begrenzt Weiterleitung"}, {"text": "Flow Label", "correct": false, "because": "QoS-Markierung"}, {"text": "Next Header", "correct": false, "because": "Protokollfolge"}]');
